def _parse_ts(value: Any) -&gt; Optional[datetime]:
    if not isinstance(value, str):
        return None
    return datetime.fromisoformat(value.replace("Z", "+00:00"))
</code></pre> <p>Status transitions follow one table:</p> From Analytics result To Snapshot any <code>ok</code>, mapping succeeds <code>ok</code> replaced, hash updated any <code>forbidden</code> <code>forbidden</code> kept in the row, never rendered for this user (see 6.8) <code>ok</code>, <code>stale</code> (snapshot exists) timeout, 5xx, network, missing result <code>stale</code> kept, footnote added <code>pending</code> (no snapshot) same transient failures <code>error</code> none any <code>not_found</code>, <code>unsupported</code>, mapping error, element removed <code>error</code> kept but flagged <p>Gotcha: one refresh must never share results across users</p> <p>The cache key starts with <code>user_key</code> because RLS makes the same chart return different rows for different users. Keying by chart alone would serve the owner's rows to a viewer. The same reasoning applies to Superset's own cache, which includes RLS clauses in its key; do not add a shared Redis layer on the Presenton side without the user in the key.</p> <p>Gotcha: never write back a slide loaded at stream start</p> <p>A refresh stream can run for many seconds while the editor autosaves the same slide through <code>PATCH /api/v1/ppt/presentation/slide_update</code> (<code>servers/fastapi/api/v1/ppt/endpoints/presentation.py:2585-2617</code>). Committing the <code>ui</code> copy that was loaded when the stream began would silently revert the user's edit. <code>_apply</code> therefore re-reads each slide with <code>session.refresh(slide, with_for_update=True)</code> immediately before patching it, so the patch lands on the latest saved <code>ui</code> and the row lock serializes it against a concurrent save on Postgres.</p> <p>Gotcha: the stream holds one <code>AsyncSession</code> for its whole life</p> <p><code>get_async_session</code> (<code>servers/fastapi/services/database.py:111</code>) yields one session per request, and a StreamingResponse keeps the request open. The service commits per slide so locks are short, but a deck with 30 bindings and a slow analytics BE holds a pooled connection for up to <code>call_timeout_s</code> times the number of batch waves. Size the pool for it in Story 9, or open a short-lived session per <code>_apply</code> call with <code>async_session_maker</code> (<code>servers/fastapi/services/database.py:53</code>).</p>

servers/fastapi/services/prompt_library/render.py (NEW)<pre><code>import copy, re
from dataclasses import dataclass
from typing import Any, Optional

from jsonschema import Draft202012Validator

from enums.tone import Tone
from enums.verbosity import Verbosity
from models.generate_presentation_request import GeneratePresentationRequest

PLACEHOLDER_RE = re.compile(r"\{\{\s*([a-z][a-z0-9_]{0,63})\s*\}\}")
_CONTROL_RE = re.compile(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]")
MAX_STRING_VALUE_CHARS = 500
MAX_RENDERED_CHARS = 8000
MAX_VARIABLES = 20


class PromptRenderError(Exception):
    def __init__(self, code: str, message: str, errors: list[dict] | None = None):
        super().__init__(message)
        self.code, self.message, self.errors = code, message, errors or []


def placeholders_in(template: str) -&gt; set[str]:
    return set(PLACEHOLDER_RE.findall(template))


def _with_defaults(schema: dict, values: dict) -&gt; dict:
    result = dict(values)
    for name, prop in (schema.get("properties") or {}).items():
        if name not in result and isinstance(prop, dict) and "default" in prop:
            result[name] = copy.deepcopy(prop["default"])
    return result


def validate_variables(schema: dict, values: dict) -&gt; dict:
    if not isinstance(values, dict) or len(values) &gt; MAX_VARIABLES:
        raise PromptRenderError("invalid_variables", "variables must be an object with at most 20 keys")
    merged = _with_defaults(schema, values)
    validator = Draft202012Validator(schema, format_checker=Draft202012Validator.FORMAT_CHECKER)
    errors = sorted(validator.iter_errors(merged), key=lambda e: [str(p) for p in e.absolute_path])
    if errors:
        raise PromptRenderError(
            "invalid_variables", "Some inputs are not valid for this prompt.",
            [{"path": "/" + "/".join(str(p) for p in e.absolute_path), "message": e.message} for e in errors[:20]],
        )
    return merged


def _clean_text(value: str) -&gt; str:
    value = _CONTROL_RE.sub("", value)
    value = " ".join(value.split())                       # single line, no blank-line "sections"
    value = value.replace("{{", "{ {").replace("}}", "} }")
    return value[:MAX_STRING_VALUE_CHARS]


def _format_value(value: Any) -&gt; str:
    if isinstance(value, bool):
        return "yes" if value else "no"
    if isinstance(value, (int, float)):
        return str(value)
    if isinstance(value, str):
        return _clean_text(value)
    if isinstance(value, list) and all(isinstance(v, (str, int, float)) for v in value):
        return ", ".join(_format_value(v) for v in value[:20])
    raise PromptRenderError("invalid_variables", "Unsupported variable type.")


def render_template(template: str, values: dict) -&gt; str:
    missing = sorted(placeholders_in(template) - values.keys())
    if missing:
        raise PromptRenderError("missing_variables", "Missing inputs.",
                                [{"path": f"/{name}", "message": "required by the prompt"} for name in missing])
    # re.sub with a callable is single pass: substituted text is never rescanned.
    rendered = PLACEHOLDER_RE.sub(lambda m: _format_value(values[m.group(1)]), template)
    if len(rendered) &gt; MAX_RENDERED_CHARS:
        raise PromptRenderError("prompt_too_long", "Rendered prompt is too long.")
    return rendered


@dataclass(frozen=True)
class RenderedPrompt:
    slug: str
    version: int
    content: str
    instructions: Optional[str]
    variables: dict
    n_slides: Optional[int]
    tone: Tone
    verbosity: Verbosity
    template: str
    language: Optional[str]


def render_prompt_item(item, variables: dict, *, template_id: Optional[str] = None,
                       n_slides: Optional[int] = None, language: Optional[str] = None) -&gt; RenderedPrompt:
    values = validate_variables(item.variables or {"type": "object"}, variables)
    return RenderedPrompt(
        slug=item.slug, version=item.version,
        content=render_template(item.prompt_template, values),
        instructions=item.instructions,                    # static by construction (Step 4.3)
        variables=values,
        n_slides=n_slides or item.default_n_slides,
        tone=Tone(item.tone), verbosity=Verbosity(item.verbosity),
        template=template_id or item.recommended_template_id or "general",
        language=language,
    )


def to_generation_request(rendered: RenderedPrompt, *, export_as: str = "pptx") -&gt; GeneratePresentationRequest:
    return GeneratePresentationRequest(
        content=rendered.content, instructions=rendered.instructions,
        n_slides=rendered.n_slides, tone=rendered.tone, verbosity=rendered.verbosity,
        template=rendered.template, language=rendered.language,
        web_search=False, include_title_slide=True, export_as=export_as,
    )
