}) {
  return (
    &lt;div
      role="group"
      aria-label={title}
      className="absolute inset-0 flex flex-col items-center justify-center gap-1.5 rounded-md border border-dashed border-[#D0D5DD] bg-[#F9FAFB]/95 p-3 text-center font-syne"
    &gt;
